void __stdcall MISC_GetValueFromD2Ini(D2IniConfigStrc * pD2IniData) {
    UINT dwIniValue;
    char* pDestField;
    char szIniPath[260];
    uint8_t nArgType;
    Fog::Source::SFile::SFILE_GetExecutableDirectory(szIniPath, 0x104);
    Storm::Source::SSTR::SStrPack(szIniPath, "D2.ini", 0x104);
    uint32_t nEntryOffset = 0;
    do {
      nArgType = (char)D2IniConfigValues[nEntryOffset].nType;
      pDestField = pD2IniData->bD2ExpMpqExistsOrLanugageCode + D2IniConfigValues[nEntryOffset].nOffset;
      switch (nArgType) {
        case '\0':
          {
            /* LPCSTR lpFileName for GetPrivateProfileIntA */ /* INT nDefault for GetPrivateProfileIntA */ /* LPCSTR lpKeyName for GetPrivateProfileIntA */ /* LPCSTR lpAppName for GetPrivateProfileIntA */ dwIniValue = GetPrivateProfileIntA(D2IniConfigValues[nEntryOffset].szAppName, D2IniConfigValues[nEntryOffset].szKeyName, D2IniConfigValues[nEntryOffset].nDefaultValue, szIniPath);
            *pDestField = dwIniValue != 0;
            break;
          }
        case '\x01':
          {
            /* LPCSTR lpFileName for GetPrivateProfileIntA */ /* INT nDefault for GetPrivateProfileIntA */ /* LPCSTR lpKeyName for GetPrivateProfileIntA */ /* LPCSTR lpAppName for GetPrivateProfileIntA */ dwIniValue = GetPrivateProfileIntA(D2IniConfigValues[nEntryOffset].szAppName, D2IniConfigValues[nEntryOffset].szKeyName, D2IniConfigValues[nEntryOffset].nDefaultValue, szIniPath);
            *(UINT*)pDestField = dwIniValue;
            break;
          }
        case '\x02':
          {
            /* LPCSTR lpFileName for GetPrivateProfileStringA */ /* DWORD nSize for GetPrivateProfileStringA */ /* LPSTR lpReturnedString for GetPrivateProfileStringA */ /* LPCSTR lpDefault for GetPrivateProfileStringA */ /* LPCSTR lpKeyName for GetPrivateProfileStringA */ /* LPCSTR lpAppName for GetPrivateProfileStringA */ GetPrivateProfileStringA(D2IniConfigValues[nEntryOffset].szAppName, D2IniConfigValues[nEntryOffset].szKeyName, "", pDestField, 0x1b, szIniPath);
            break;
          }
      }

      nEntryOffset++;
    } while (nEntryOffset < 58);
}

int32_t __stdcall INI_FindConfigValueIndex(uint8_t * pbArgName) {
    int nIndex = 0;
    char* pbEntry = D2IniConfigValues[0].szCmdLineArg;
    uint32_t nByteOffset = 0;
    uint8_t* pbArgCursor = pbArgName;
    char* pbEntryStart = pbEntry;
    do {
      int nCmp;
      nCmp = strcmp(pbEntry, (char*)pbArgCursor);
      if (!nCmp) {
        return nIndex;
      }

      nByteOffset += 0x5c;
      nIndex++;
      pbEntry = pbEntryStart + 0x5c;
      pbArgCursor = pbArgName;
      pbEntryStart = pbEntry;
      if (nByteOffset >= 0x14d8) {
        return -1;
      }
    } while (true);
}

uint32_t __fastcall INI_IsDelimiterChar(char cChar) {
    char szDelimiters[4];
    memcpy(szDelimiters, " \t\n:", 4);
    int i = 0;
    do {
      if (szDelimiters[i] == cChar) {
        return 1;
      }

      i++;
    } while (i < 4);

    return 0;
}

static void INI_StripDelimiters(char * szText) {
    int nWriteIdx;
    int nDelimIdx;
    char aWorkBuf[260];
    char cChar;
    char* pCursor;
    pCursor = szText;
    do {
      cChar = *pCursor;
      pCursor[(intptr_t)(aWorkBuf + (4 - (intptr_t)szText))] = cChar;
      pCursor++;
    } while (cChar != '\0');

    pCursor = szText;
    pCursor = pCursor + strlen(pCursor) + 1;
    int nLen;
    nLen = (intptr_t)pCursor - (intptr_t)(szText + 1);
    int nReadIdx;
    nReadIdx = 0;
    if (nLen > 0) {
      memcpy(aWorkBuf, " \t\n:", 4);
      do {
        nWriteIdx = 0;
        while (aWorkBuf[nWriteIdx] != szText[nReadIdx]) {
          nWriteIdx++;
          if (nWriteIdx >= 4) {
            goto copy_token;
          }
        }

        nReadIdx++;
      } while (nReadIdx < nLen);
    }

    copy_token:
    nWriteIdx = 0;
    if (nReadIdx < nLen) {
      memcpy(aWorkBuf, " \t\n:", 4);
      do {
        nDelimIdx = 0;
        do {
          if (aWorkBuf[nDelimIdx] == aWorkBuf[nReadIdx + 4]) {
            szText[nWriteIdx] = '\0';
            return;
          }

          nDelimIdx++;
        } while (nDelimIdx < 4);

        szText[nWriteIdx] = aWorkBuf[nReadIdx + 4];
        nReadIdx++;
        nWriteIdx++;
      } while (nReadIdx < nLen);
    }

    szText[nWriteIdx] = '\0';
}

int __fastcall INI_ParseCommandLineArg(uint8_t * pbArgName, char * szCmdLine, char * pOutValue) {
    char szArgNameBuf[256];
    char cChar;
    int nDstOffset;
    char* pCursor;
    int nCmdLen = (int)strlen(szCmdLine);
    int nNameLen = 0;
    int32_t nConfigIdx = -1;
    if (nCmdLen >= 0x100) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (void*)(DWORD)Fog::Src::ErrorManager::GetInstructionPointer(), 0x103);
      exit(-1);
    }
    if (nCmdLen > 0) {
      nDstOffset = -(int)szCmdLine;
      do {
        cChar = *szCmdLine;
        if (cChar == '-' || cChar == '\0') {
          break;
        }

        szCmdLine[(intptr_t)(szArgNameBuf + nDstOffset)] = cChar;
        nNameLen++;
        szCmdLine++;
      } while (nNameLen < nCmdLen);
    }

    pCursor = szArgNameBuf;
    szArgNameBuf[nNameLen] = '\0';
    szArgNameBuf[nNameLen + 1] = '\0';
    strcpy((char*)pbArgName, pCursor);
    uint8_t* pbScan = pbArgName;
    pbScan = pbScan + strlen((char*)pbScan) + 1;
    nCmdLen = (intptr_t)pbScan - (intptr_t)(pbArgName + 1);
    uint8_t byChar = *pbArgName;
    pbScan = pbArgName;
    while (byChar) {
      byChar = *pbScan;
      if ((char)byChar >= 'A' && (char)byChar <= 'Z') {
        *pbScan = byChar + 0x20;
      }

      pbScan++;
      byChar = *pbScan;
    }

    bool bStillSearching = true;
    while (nCmdLen && bStillSearching) {
      pbArgName[nCmdLen] = 0;
      nConfigIdx = INI_FindConfigValueIndex(pbArgName);
      if (nConfigIdx != -1) {
        bStillSearching = false;
      }

      nCmdLen--;
    }

    pbScan = pbArgName + 1;
    pbArgName = pbArgName + strlen((char*)pbArgName) + 1;
    nCmdLen = 0;
    while (szArgNameBuf[0] != '\0') {
      szArgNameBuf[0] = szArgNameBuf[nCmdLen + 1];
      pOutValue[nCmdLen] = pbArgName[(intptr_t)(szArgNameBuf + (nCmdLen - (intptr_t)pbScan))];
      nCmdLen++;
    }

    pOutValue[nCmdLen] = '\0';
    INI_StripDelimiters(pOutValue);
    return nConfigIdx;
}

